{"path":"test_issue_checks.py","content":"from config import merge, load_layers

def test_requirements():
    # 1. Nested dicts merge recursively
    base = {"db": {"host": "a", "port": 1}}
    override = {"db": {"port": 2}}
    res = merge(base, override)
    assert res == {"db": {"host": "a", "port": 2}}

    # 2. Lists are replaced, not concatenated
    base = {"items": [1, 2, 3]}
    override = {"items": [4, 5]}
    res = merge(base, override)
    assert res == {"items": [4, 5]}

    # 3. Override value of None removes that key from the result (at any depth)
    base = {"db": {"host": "a", "port": 1}, "debug": True}
    override = {"db": {"port": None}, "debug": None}
    res = merge(base, override)
    assert res == {"db": {"host": "a"}}

    # 4. If one side is a dict and the other is not, the override wins
    assert merge({"a": 1}, {"a": {"b": 2}}) == {"a": {"b": 2}}
    assert merge({"a": {"b": 2}}, {"a": 1}) == {"a": 1}

    # 5. Neither input is modified, and the result shares no dicts or lists with inputs
    base = {"db": {"host": "a", "port": 1}, "items": [1, 2]}
    base_copy = copy_structure(base)
    override = {"db": {"port": 2}, "items": [3]}
    override_copy = copy_structure(override)

    res = merge(base, override)
    assert base == base_copy
    assert override == override_copy

    # Mutate result and check inputs don't change
    res["db"]["port"] = 999
    res["items"].append(999)
    assert base["db"]["port"] == 1
    assert base["items"] == [1, 2]

    # 6. load_layers(*layers) works
    res_layers = load_layers({"a": 1}, {"a": 2, "b": 3}, {"a": None})
    assert res_layers == {"b": 3}

def copy_structure(d):
    import copy
    return copy.deepcopy(d)
